public class TarUtils_parseOctal_TriageGen2Test {





















    @Test
    public void testParseOctal_AllSpaces() {
        // If the buffer contains only spaces, the while loop for trimming 
        // might reduce end to start.
        byte[] buffer = "    ".getBytes();
        // length 4, all spaces. 
        // start will increment to 4. end will decrement to 0.
        // loop start < end will not execute.
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(0L, result);
    }


}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen2Test {























    @Test
    public void testParseOctal_MixedTrailing() {
        // Testing the trailer logic: byte trailer = buffer[end - 1];
        // while (start < end && (trailer == 0 || trailer == ' '))
        byte[] buffer = "0123 \0 ".getBytes(); 
        // Indices: 0:0, 1:1, 2:2, 3:3, 4:' ', 5:0, 6:' '
        // length 7. end = 7.
        // trailer = buffer[6] = ' '
        // end becomes 6, trailer = buffer[5] = 0
        // end becomes 5, trailer = buffer[4] = ' '
        // end becomes 4, trailer = buffer[3] = '3' -> loop stops.
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(10L, result); // 0123 octal = 1*8 + 2 = 10? No, 1*8 + 2 = 10 is wrong.
        // 0123 octal: 0*64 + 1*8 + 2*1 + 3 = 11. Let's re-calc.
        // index 0:'0', 1:'1', 2:'2', 3:'3'
        // result = 0
        // start 0: res = 0*8 + 0 = 0
        // start 1: res = 0*8 + 1 = 1
        // start 2: res = 1*8 + 2 = 10
        // start 3: res = 10*8 + 3 = 83
        // Wait, the math in my head: 1*8 + 2*1 + 3 is not right.
        // 0123 octal = (1 * 8^2) + (2 * 8^1) + (3 * 8^0) = 64 + 16 + 3 = 83.
        // The code uses: result = (result << 3) + (currentByte - '0')
        // 0: (0<<3)+0 = 0
        // 1: (0<<3)+1 = 1
        // 2: (1<<3)+2 = 10
        // 3: (10<<3)+3 = 83. Correct.
        assertEquals(83L, result);
    }
}
